// Generates the client's copy of the kit contracts and packs. Nothing it writes is edited by hand.
//
//   dart run tool/gen_contracts.dart           regenerate
//   dart run tool/gen_contracts.dart --check   exit 1 if the generated files are out of date
//
// Inputs  (read-only):  ../kit/contracts/json-schema.json, ../kit/contracts/schemas.ts, ../kit/packs/*.json
// Outputs: lib/core/generated/contracts.g.dart   (wire schemas + constants)
//          assets/packs/*.json                   (byte-for-byte copies, bundled into the app)
import 'dart:convert';
import 'dart:io';

void main(List<String> args) {
  final check = args.contains('--check');
  final root = File.fromUri(Platform.script).parent.parent.path;
  final kit = Platform.environment['BAKEOFF_KIT_DIR'] ?? '$root/../kit';
  final outputs = <String, List<int>>{};

  // ---- contracts ----
  final schemaText = File('$kit/contracts/json-schema.json').readAsStringSync();
  final schemas = jsonDecode(schemaText) as Map<String, dynamic>;
  final ts = File('$kit/contracts/schemas.ts').readAsStringSync();

  // Constants that exist only as code in schemas.ts are lifted out by pattern. If the kit
  // changes shape so that a pattern no longer matches, generation fails instead of guessing.
  final maxPush = RegExp(r'MAX_MUTATIONS_PER_PUSH\s*=\s*(\d+)').firstMatch(ts);
  if (maxPush == null) fail('MAX_MUTATIONS_PER_PUSH not found in schemas.ts');
  final decimals = <String, Map<String, int>>{};
  for (final m in RegExp(r"type === '(\w+)' && !decimals\(v\.(\w+), (\d+)\)").allMatches(ts)) {
    decimals[m.group(1)!] = {m.group(2)!: int.parse(m.group(3)!)};
  }
  if (decimals.isEmpty) fail('no decimals(...) rules found in schemas.ts');
  final readerRule = RegExp(r"source === '(\w+)' && !body\.data\.reader\?\.(\w+)").allMatches(ts);
  final requiredReader = {for (final m in readerRule) m.group(1)!: m.group(2)!};

  final sources = (schemas['Source']['enum'] as List).cast<String>();
  final iso = schemas['IsoSeconds']['pattern'] as String;
  final eventName = schemas['AnalyticsEvent']['properties']['name']['const'] as String;
  final valueSchemas = {
    for (final k in schemas.keys.where((k) => k.startsWith('Value_'))) k.substring(6): schemas[k],
  };

  final b = StringBuffer()
    ..writeln('// GENERATED by tool/gen_contracts.dart from kit/contracts. DO NOT EDIT.')
    ..writeln('// Regenerate with: dart run tool/gen_contracts.dart')
    ..writeln('// ignore_for_file: prefer_single_quotes, lines_longer_than_80_chars')
    ..writeln()
    ..writeln('/// Observation sources (contract `Source`).')
    ..writeln('const List<String> kSources = ${jsonEncode(sources)};')
    ..writeln()
    ..writeln('/// Canonical timestamp pattern (contract `IsoSeconds`).')
    ..writeln('const String kIsoSecondsPattern = r"$iso";')
    ..writeln()
    ..writeln('/// Contract `MAX_MUTATIONS_PER_PUSH`.')
    ..writeln('const int kMaxMutationsPerPush = ${maxPush.group(1)};')
    ..writeln()
    ..writeln('/// Decimal places the contract demands, by observation type then value field.')
    ..writeln('const Map<String, Map<String, int>> kValueDecimals = ${jsonEncode(decimals)};')
    ..writeln()
    ..writeln('/// Reader field the contract demands for a source.')
    ..writeln('const Map<String, String> kRequiredReaderField = ${jsonEncode(requiredReader)};')
    ..writeln()
    ..writeln('/// The only analytics event name the gate lets through.')
    ..writeln('const String kAnalyticsEventName = ${jsonEncode(eventName)};')
    ..writeln()
    ..writeln('/// JSON Schema of the value object, by observation type (contract `ValueByType`).')
    ..writeln('const Map<String, Object?> kValueSchemas = ${dartLiteral(valueSchemas)};')
    ..writeln()
    ..writeln('/// Every wire schema in kit/contracts/json-schema.json, by name.')
    ..writeln('const Map<String, Object?> kSchemas = ${dartLiteral(schemas)};');
  outputs['$root/lib/core/generated/contracts.g.dart'] = utf8.encode(b.toString());

  // ---- packs ----
  final packFiles = Directory('$kit/packs').listSync().whereType<File>().where((f) => f.path.endsWith('.json')).toList()
    ..sort((a, b) => a.path.compareTo(b.path));
  for (final f in packFiles) {
    outputs['$root/assets/packs/${f.uri.pathSegments.last}'] = f.readAsBytesSync();
  }

  var stale = 0;
  for (final e in outputs.entries) {
    final f = File(e.key);
    final same = f.existsSync() && _eq(f.readAsBytesSync(), e.value);
    if (same) continue;
    stale++;
    if (check) {
      stderr.writeln('OUT OF DATE: ${e.key}');
    } else {
      f.parent.createSync(recursive: true);
      f.writeAsBytesSync(e.value);
      stdout.writeln('wrote ${e.key}');
    }
  }
  // A pack removed from the kit must not linger in the app bundle.
  final assetDir = Directory('$root/assets/packs');
  if (assetDir.existsSync()) {
    for (final f in assetDir.listSync().whereType<File>()) {
      if (!outputs.containsKey(f.path) && !outputs.keys.any((k) => File(k).absolute.path == f.absolute.path)) {
        stale++;
        if (check) {
          stderr.writeln('STRAY: ${f.path}');
        } else {
          f.deleteSync();
        }
      }
    }
  }
  if (check && stale > 0) {
    stderr.writeln('Generated files are out of date. Run: dart run tool/gen_contracts.dart');
    exit(1);
  }
  stdout.writeln(check ? 'generated files are up to date' : 'done');
}

Never fail(String message) {
  stderr.writeln('gen_contracts: $message');
  exit(2);
}

bool _eq(List<int> a, List<int> b) {
  if (a.length != b.length) return false;
  for (var i = 0; i < a.length; i++) {
    if (a[i] != b[i]) return false;
  }
  return true;
}

/// JSON value -> Dart const literal (raw strings so regex patterns survive untouched).
String dartLiteral(Object? v) {
  if (v is Map) {
    return '{${v.entries.map((e) => '${_str(e.key as String)}: ${dartLiteral(e.value)}').join(', ')}}';
  }
  if (v is List) return '[${v.map(dartLiteral).join(', ')}]';
  if (v is String) return _str(v);
  return jsonEncode(v);
}

String _str(String s) {
  if (!s.contains('"') && !s.contains('\n')) return 'r"$s"';
  return jsonEncode(s).replaceAll(r'$', r'\$');
}
